    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    interior = [(r, c) for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
                    if not interior or any(grid[r][c] != bg for r, c in interior):
                        continue
                    sides = [
                        [grid[r0][c] for c in range(c0, c1 + 1)],
                        [grid[r1][c] for c in range(c0, c1 + 1)],
                        [grid[r][c0] for r in range(r0, r1 + 1)],
                        [grid[r][c1] for r in range(r0, r1 + 1)],
                    ]
                    # Determine a frame color that occupies every side.
                    candidates = set(v for side in sides for v in side if v != bg)
                    frame = None
                    for color in candidates:
                        if all(all(v == color for v in side) for side in sides):
                            frame = color
                            break
                    if frame is None:
                        continue
                    ih, iw = r1 - r0 - 1, c1 - c0 - 1
                    area = ih * iw
                    fill = 2 if area % 2 == 0 else 7
                    for r, c in interior:
                        out[r][c] = fill
                    if area % 2:
                        # Odd-sized cavities carry a single accent at their center.
                        out[r0 + 1 + ih // 2][c0 + 1 + iw // 2] = 7
    return out
