    colors = {v for row in grid for v in row if v != bg}

    for r0 in range(h - 2):
        for r1 in range(r0 + 2, h):
            for c0 in range(w - 2):
                for c1 in range(c0 + 2, w):
                    cavity = [(r, c) for r in range(r0 + 1, r1)
                              for c in range(c0 + 1, c1)]
                    if any(grid[r][c] != bg for r, c in cavity):
                        continue
                    # Closed, one-color perimeter.
                    sides = [
                        [grid[r0][c] for c in range(c0, c1 + 1)],
                        [grid[r1][c] for c in range(c0, c1 + 1)],
                        [grid[r][c0] for r in range(r0, r1 + 1)],
                        [grid[r][c1] for r in range(r0, r1 + 1)],
                    ]
                    for color in colors:
                        if all(all(v == color for v in side) for side in sides):
                            fill = 7 if len(cavity) == 1 else 2
                            for r, c in cavity:
