 "content": "from collections import Counter


def transform(grid):
    """Fill hollow rectangular frames: odd-area cavities with 7, even with 2."""
    height = len(grid)
    widths = {len(row) for row in grid}
    if height == 0 or len(widths) != 1:
        return [row[:] for row in grid]

    width = widths.pop()
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    result = [row[:] for row in grid]
    frame_colors = {value for row in grid for value in row if value != background}

    for top in range(height - 2):
        for bottom in range(top + 2, height):
            for left in range(width - 2):
                for right in range(left + 2, width):
                    cavity = [
                        (r, c)
                        for r in range(top + 1, bottom)
                        for c in range(left + 1, right)
                    ]
                    if not cavity or any(grid[r][c] != background for r, c in cavity):
                        continue

                    perimeter = (
                        [(top, c) for c in range(left, right + 1)]
                        + [(bottom, c) for c in range(left, right + 1)]
                        + [(r, left) for r in range(top + 1, bottom)]
                        + [(r, right) for r in range(top + 1, bottom)]
                    )
                    for color in frame_colors:
                        if all(grid[r][c] == color for r, c in perimeter):
                            fill = 7 if len(cavity) % 2 else 2
                            for r, c in cavity:
                                result[r][c] = fill
                            break
    return result
